sp_widget.client_script:
function($scope, $rootScope) {
  // Inicializa sem seleção
  $scope.anoSelecionado = "";

  // Quando o ano mudar, emite evento global
  $scope.anoChanged = function() {
    $rootScope.$broadcast('anoSelecionado', $scope.anoSelecionado);
  };
  console.log('Ano enviado para filtro:', $scope.anoSelecionado);
}

sp_widget.css:
canvas {
  margin: 0 auto;
  display: block;
}
label{
margin-top:200px;
}

sp_widget.script:
(function() {
  var anos = [];
  var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');
  gr.orderByDesc('u_ano');
  gr.query();

  var anosUnicos = {};
  while (gr.next()) {
    var ano = gr.getValue('u_ano');
    if (!anosUnicos[ano]) {
      anos.push(ano);
      anosUnicos[ano] = true;
    }
  }

  data.anos = anos;
})();
